const EFFECTS=[];
function add(type,category,names){for(let name of names.split('|')){const m=name.match(/^(.*?)\s*\+(\d+)~(\d+)$/);let variants=m?Array.from({length:+m[3]-+m[2]+1},(_,i)=>m[1]+(+m[2]+i?`+${+m[2]+i}`:'')):[name.replace(/\s+\+/g,'+')];for(let n of variants)EFFECTS.push({id:type+':'+n,type,category,name:n,character:n.match(/^【(.+?)】/)?.[1]||''});}}
