const ALWAYS_PENALTY=new Set(['最大HP上昇','最大FP上昇','最大スタミナ上昇']);
const PENALTY_FROM_ONE=new Set(['属性攻撃力上昇','魔術強化','祈祷強化','ガードカウンター強化','脂アイテム使用時、追加で物理攻撃力上昇','敵を倒した時、アーツゲージ増加','致命の一撃で、アーツゲージ増加','ガード成功時、アーツゲージ増加','物理カット率上昇','属性カット率上昇','魔力カット率上昇','炎カット率上昇','雷カット率上昇','聖カット率上昇','刺突カウンター発生時、HP回復','ダメージを受けた直後、攻撃によりHPの一部を回復','毒状態の敵に対する攻撃を強化','腐敗状態の敵に対する攻撃を強化','凍傷状態の敵に対する攻撃を強化','周囲で睡眠状態の発生時、攻撃力上昇','周囲で発狂状態の発生時、攻撃力上昇']);
const PENALTY_FROM_THREE=new Set(['物理攻撃力上昇','魔力攻撃力上昇','炎攻撃力上昇','雷攻撃力上昇','聖攻撃力上昇']);
for(const e of EFFECTS){const m=e.name.match(/^(.*)\+(\d+)$/),base=m?m[1]:e.name,level=m?Number(m[2]):0;e.hasPenalty=e.type==='deep'&&(ALWAYS_PENALTY.has(e.name)||(PENALTY_FROM_ONE.has(base)&&level>=1)||(PENALTY_FROM_THREE.has(base)&&level>=3));}
